/**
 * @param {number[]} nums
 * @return {number}
 */
var minimizeSum = function(nums) {
    nums.sort((a, b) => a - b);

    const n = nums.length;
    const diff = nums[n - 1] - nums[0];

    const oneLeft = nums[1] - nums[0];
    const twoLeft = nums[2] - nums[1] + oneLeft;
    const oneRight = nums[n - 1] - nums[n - 2];
    const twoRight = nums[n - 2] - nums[n - 3] + oneRight;

    return diff - Math.max(
        oneLeft + oneRight,
        twoLeft,
        twoRight
    );
};
